import VisibilityOutlinedIcon from "@mui/icons-material/VisibilityOutlined";
import { Box, Button, IconButton, Stack, Tooltip, Typography } from "@mui/material";
import Link from "next/link";
import { ReactNode } from "react";
import PremiumDataTable, { PremiumDataTableColumn } from "@/components/common/PremiumDataTable";
import dicConstant from "@/constants/Constant.json";

const employees = [
  { id: "E001", name: "Ava Johnson", department: "Engineering", role: "Frontend Developer" },
  { id: "E002", name: "Liam Smith", department: "HR", role: "HR Executive" },
  { id: "E003", name: "Noah Davis", department: "Finance", role: "Accountant" }
];

type EmployeeGridRow = {
  id: ReactNode;
  name: ReactNode;
  department: ReactNode;
  role: ReactNode;
  action: ReactNode;
  sortId: string;
  sortName: string;
  sortDepartment: string;
  sortRole: string;
};

export default function EmployeesPage() {
  const columns: PremiumDataTableColumn<EmployeeGridRow>[] = [
    { field: "id", headerName: dicConstant.employees.grid.id, sortable: true },
    { field: "name", headerName: dicConstant.employees.grid.name, sortable: true },
    { field: "department", headerName: dicConstant.employees.grid.department, sortable: true },
    { field: "role", headerName: dicConstant.employees.grid.role, sortable: true },
    { field: "action", headerName: dicConstant.employees.grid.action, sortable: false, filterable: false, exportable: false, align: "center" }
  ];

  const rows: EmployeeGridRow[] = employees.map((dicEmployee) => ({
    id: <Typography sx={{ color: "#94a3b8", fontWeight: 500 }}>{dicEmployee.id}</Typography>,
    name: <Typography sx={{ color: "#0f172a", fontWeight: 600 }}>{dicEmployee.name}</Typography>,
    department: <Typography sx={{ color: "#64748b" }}>{dicEmployee.department}</Typography>,
    role: <Typography sx={{ color: "#64748b" }}>{dicEmployee.role}</Typography>,
    action: (
      <Tooltip title="View details" arrow>
        <IconButton
          component={Link}
          href={`/employees/${dicEmployee.id}`}
          aria-label="View details"
          size="small"
          sx={{
            width: 34,
            height: 34,
            transition: "all 0.2s ease",
            "&:hover": { backgroundColor: "rgba(37,99,235,0.08)" }
          }}
        >
          <VisibilityOutlinedIcon sx={{ fontSize: 20, color: "#475569" }} />
        </IconButton>
      </Tooltip>
    ),
    sortId: dicEmployee.id,
    sortName: dicEmployee.name,
    sortDepartment: dicEmployee.department,
    sortRole: dicEmployee.role
  }));

  const sortableRows = rows.map((dicRow) => ({
    ...dicRow,
    id: dicRow.id,
    name: dicRow.name,
    department: dicRow.department,
    role: dicRow.role,
    // Hidden sort keys for stable primitive sorting in reusable table.
    idValue: dicRow.sortId,
    nameValue: dicRow.sortName,
    departmentValue: dicRow.sortDepartment,
    roleValue: dicRow.sortRole
  }));

  const sortableColumns: PremiumDataTableColumn<(typeof sortableRows)[number]>[] = [
    { field: "idValue", headerName: dicConstant.employees.grid.id, sortable: true, exportable: false, filterable: true },
    { field: "nameValue", headerName: dicConstant.employees.grid.name, sortable: true, exportable: false, filterable: true },
    { field: "departmentValue", headerName: dicConstant.employees.grid.department, sortable: true, exportable: false, filterable: true },
    { field: "roleValue", headerName: dicConstant.employees.grid.role, sortable: true, exportable: false, filterable: true },
    { field: "action", headerName: dicConstant.employees.grid.action, sortable: false, filterable: false, exportable: false, align: "center" }
  ];

  const lstRenderRows = sortableRows.map((dicRow) => ({
    ...dicRow,
    idValue: dicRow.id,
    nameValue: dicRow.name,
    departmentValue: dicRow.department,
    roleValue: dicRow.role
  }));

  return (
    <Stack
      spacing={4}
      sx={{
        animation: "employeesFadeIn 200ms ease-out",
        "@keyframes employeesFadeIn": {
          from: { opacity: 0, transform: "translateY(8px)" },
          to: { opacity: 1, transform: "translateY(0)" }
        }
      }}
    >
      <Box>
        <Typography sx={{ fontSize: { xs: 30, md: 34 }, fontWeight: 700, lineHeight: 1.15 }}>
          {dicConstant.employees.pageTitle}
        </Typography>
        <Typography sx={{ color: "#64748b", mt: 1 }}>Manage and monitor your workforce.</Typography>
      </Box>

      <Button
        variant="contained"
        href="/employees/new"
        sx={{
          alignSelf: "flex-start",
          height: 48,
          px: 2.5,
          borderRadius: "14px",
          backgroundColor: "#2563eb",
          boxShadow: "0 6px 16px rgba(37,99,235,0.35)",
          transition: "all 0.15s ease",
          "&:hover": {
            transform: "translateY(-1px)",
            backgroundColor: "#1d4ed8"
          }
        }}
      >
        {dicConstant.employees.addButton}
      </Button>

      <PremiumDataTable
        columns={sortableColumns}
        rows={lstRenderRows}
        rowIdField="idValue"
        showExportOptions
        exportFileName="employees-list"
      />
    </Stack>
  );
}
